-- Bed: Sleep Mode gets user-editable sleep hours (time params, schema 2).
-- Apps before schema 2 show it as "Update the app"; the update fires Realtime and touches updated_at.
update public.recipes set doc = '{"id":"bed-sleep","schemaVersion":2,"version":2,"title":"Bed: Sleep Mode","description":"Tap at night to block distracting apps and silence notifications. Tap again in the morning to end sleep mode and start your morning routine.","placementHint":"Stick it on your bedside table where your phone stays overnight.","mode":"toggle","params":[{"key":"autoOffMinutes","type":"duration","label":"Wake up mode starts after","default":480,"min":240,"max":720},{"key":"sleepStart","type":"time","label":"Sleep mode can start from","default":1260,"min":0,"max":1439},{"key":"sleepEnd","type":"time","label":"until","default":300,"min":0,"max":1439},{"key":"strictMinutes","type":"duration","label":"Can''t turn off with the tag for","default":0,"min":0,"max":480}],"autoOffMinutes":"{{autoOffMinutes}}","strictMinutes":"{{strictMinutes}}","rules":[{"when":{"time":"{{sleepStart}}-{{sleepEnd}}"},"actions":[{"type":"blockGroups","groups":["social","video","games"]},{"type":"dnd"}]},{"actions":[{"type":"log","label":"Bed tap outside night hours"}]}],"endActions":[{"type":"checklist","title":"Good morning","items":["Drink a glass of water","Make the bed","Put on workout clothes"]}]}'::jsonb where id = 'bed-sleep';
